pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 120.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Last fitting bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 2.0;

    // Prefer bins whose residual deviates favorably from the mean (consolidate).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if the next item would fit exactly in the post residual, reward;
    // if post residual is too small for the next item, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // New-bin candidate: only attractive when current fit would create dead space.
    if bin_residual == bin_capacity {
        score = 40.0 + (open_bins_count as f64) * 0.5;
        if post_residual == 0 || post_residual >= 30 {
            score -= 35.0;
        }
        if fitting_bins_count == 1 {
            score += 80.0; // never open a new bin when this is the last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Adaptive dead-space threshold tied to lookahead item size.
    let dead_threshold = 10.0_f64.max((next_item_size as f64 * 0.6).min(50.0));
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 24.0 + (dead_threshold - post_residual as f64) * 2.8;
    }

    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 48.0;
    } else if post_residual <= 4 {
        // Tiny gap is nearly perfect: reward closing it out.
        score -= 20.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Last fitting bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: graded reward for leaving a residual the next item can use.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 22.0; // exact match for next item: excellent handoff
        } else if gap <= 4 {
            score -= 16.0;
        } else if gap <= 12 {
            score -= 7.0;
        } else if gap <= 24 {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual too small for next item: penalize dead-space creation.
        let waste_ratio = (post_residual as f64) / (next_item_size as f64).max(1.0);
        let soft = if post_residual <= 3 { 0.4 } else { 1.0 };
        score += (8.0 + waste_ratio * 12.0) * soft;
    }

    // Consolidation pressure: prefer bins whose residual sits below the mean.
    if fitting_bins_count > 2 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.4 {
        score -= 4.0;
    }
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate logic: open a new bin only for large items or when
    // existing fits would strand unusable space.
    if bin_residual == bin_capacity {
        let load = item_size as f64 / bin_capacity as f64;
        if load < 0.25 && fitting_bins_count > 0 {
            score -= 6.0; // small item: cheap to place anywhere, avoid new bin
        } else {
            score += 4.0 * load;
        }
        if post_residual == 0 || post_residual >= 30 {
            score -= 35.0;
        }
        // Prefer a fresh bin when the next item is large and would be stranded
        // by any residual left behind in existing bins.
        if next_item_size >= 50 && post_residual < next_item_size && post_residual > 0 {
            score -= 18.0;
        }
        if fitting_bins_count == 1 {
            score += 80.0; // never open a new bin when this is the last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Adaptive dead-space threshold tied to lookahead item size.
    let dead_threshold = 10.0_f64.max((next_item_size as f64 * 0.6).min(50.0));
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 24.0 + (dead_threshold - post_residual as f64) * 2.8;
    }

    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 48.0;
    } else if post_residual <= 4 {
        // Tiny gap is nearly perfect: reward closing it out.
        score -= 20.0;
    }

    // Reward tight fits relative to bin capacity, with a superlinear bonus
    // for very full placements (combats dead-space accumulation).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;
    if fill_ratio > 0.8 {
        score -= (fill_ratio - 0.8) * 60.0;
    }

    // Last fitting bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: graded reward for leaving a residual the next item can use.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 26.0; // exact match for next item: excellent handoff
        } else if gap <= 4 {
            score -= 16.0;
        } else if gap <= 12 {
            score -= 7.0;
        } else if gap <= 24 {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual too small for next item: penalize dead-space creation.
        let waste_ratio = (post_residual as f64) / (next_item_size as f64).max(1.0);
        let soft = if post_residual <= 3 { 0.4 } else { 1.0 };
        score += (8.0 + waste_ratio * 12.0) * soft;
    }

    // Consolidation pressure: prefer bins whose residual sits below the mean.
    if fitting_bins_count > 2 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.4 {
        score -= 4.0;
    }
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Two-item lookahead coupling: reward residuals that can host the next
    // item with usable leftover space (soft two-step chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size {
            score -= 6.0; // residual can host next item twice: strong chain
        } else if after_next > 0 && after_next <= 6 {
            score -= 4.0; // leaves a nearly-closed gap after next placement
        }
    }

    // Late-stream pressure: as the stream progresses, favor compacting into
    // existing bins more aggressively to squeeze out extra bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.6 && bin_residual < bin_capacity {
        score -= progress * 6.0;
    }

    // New-bin candidate logic: open a new bin only for large items or when
    // existing fits would strand unusable space.
    if bin_residual == bin_capacity {
        let load = item_size as f64 / bin_capacity as f64;
        if load < 0.25 && fitting_bins_count > 0 {
            score -= 6.0; // small item: cheap to place anywhere, avoid new bin
        } else {
            score += 4.0 * load;
        }
        if post_residual == 0 || post_residual >= 30 {
            score -= 35.0;
        }
        // Prefer a fresh bin when the next item is large and would be stranded
        // by any residual left behind in existing bins.
        if next_item_size >= 50 && post_residual < next_item_size && post_residual > 0 {
            score -= 18.0;
        }
        // Avoid opening a new bin for a large item when an existing bin leaves
        // a residual the next item could still consume.
        if load >= 0.25 && next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        if fitting_bins_count == 1 {
            score += 80.0; // never open a new bin when this is the last chance
        }
        // Extra guard: with several fitting bins and a small item, strongly
        // discourage wasting a fresh bin.
        if load < 0.35 && fitting_bins_count >= 2 {
            score += 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Adaptive dead-space threshold tied to lookahead item size.
    let dead_threshold = 12.0_f64.max((next_item_size as f64 * 0.55).min(45.0));
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 26.0 + (dead_threshold - post_residual as f64) * 2.5;
    }

    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 52.0;
    } else if post_residual <= 3 {
