    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 32.0;
    if fill_ratio > 0.75 {
        score -= (fill_ratio - 0.75) * 70.0;
    }

    // Last fitting bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 65.0;
    }

    // Lookahead: graded reward for leaving a residual the next item can use.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap <= 4 {
            score -= 18.0;
        } else if gap <= 12 {
            score -= 8.0;
        } else if gap <= 24 {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        let waste_ratio = (post_residual as f64) / (next_item_size as f64).max(1.0);
        let soft = if post_residual <= 3 { 0.35 } else { 1.0 };
        score += (9.0 + waste_ratio * 13.0) * soft;
    }

    // Consolidation pressure: prefer bins whose residual sits below the mean.
    if fitting_bins_count > 2 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.35 {
        score -= 5.0;
    }
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Two-item lookahead coupling: reward residuals that can host the next item twice.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size {
            score -= 7.0;
        } else if after_next > 0 && after_next <= 6 {
            score -= 4.0;
        }
    }

    // Late-stream pressure: favor compacting into existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.55 && bin_residual < bin_capacity {
        score -= progress * 8.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let load = item_size as f64 / bin_capacity as f64;
        if load < 0.25 && fitting_bins_count > 0 {
            score -= 8.0;
        } else {
            score += 5.0 * load;
        }
        if post_residual == 0 || post_residual >= 28 {
            score -= 38.0;
        }
        // Prefer a fresh bin when the next item is large and would be stranded.
        if next_item_size >= 45 && post_residual < next_item_size && post_residual > 0 {
            score -= 20.0;
        }
        // Avoid opening a new bin when existing bin leaves a usable residual.
        if load >= 0.25 && next_item_size > 0 && post_residual >= next_item_size {
            score += 12.0;
        }
        if fitting_bins_count == 1 {
            score += 85.0;
        }
        if load < 0.35 && fitting_bins_count >= 2 {
            score += 16.0;
        }
        // Mid-size item with many fitting bins: keep bins consolidated.
        if load < 0.6 && fitting_bins_count >= 4 {
            score += 8.0;
        }
    }

    score
}

