pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold any plausible
    // future item (min size 1..100 unknown; treat gaps < 25 as increasingly wasted).
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 25.0 {
            score += (25.0 - pr) * 4.0; // steep penalty for tiny unusable gaps
        } else if pr < 50.0 {
            score += (50.0 - pr) * 1.0;
        }
    }

    // Reward tight fits (high fill ratio of the bin).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Open-bin pressure: with many open bins, discourage spreading; prefer new bin
    // only when fits are poor. Mild penalty scaling with open_bins_count.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when the item fits
    // badly everywhere else. Give it a moderate default score.
    if bin_residual == bin_capacity {
        score += 10.0;
        // If the item nearly fills a fresh bin, opening is attractive.
        if (item_size as f64) > 0.7 * bin_capacity as f64 {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits the post-residual exactly or well, reward it.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        let slack = post_residual as f64 - next_item_size as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the gap -> dead space likely
        score += 8.0;
    }

    // Progress-based adaptation: late in the stream, be more conservative,
    // prefer packing into existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

