pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Stream-progress coupling: later in stream, penalize wasted residual more strongly
    score += 20.0 * progress * norm_pr * norm_pr;

    // Penalize small-but-nonzero dead space quadratically (unusable slivers)
    let dead = norm_pr * (1.0 - norm_pr);
    score -= 15.0 * dead * dead * (1.0 - progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 + 0.15 * next_item_size as f64;
    }

    // Mild penalty for spreading across many open bins vs. consolidating
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Alignment with mean residual: prefer bins near the mean to keep balance
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual (tight fit)
    let mut score = post;

    // Harmonic class of the leftover: classify post_residual into "usable" buckets
    // Leftovers that can host common small items (multiples / halves) are valuable.
    let pr = post_residual;
    let usable = if pr == 0 { 3.0 }
        else if pr >= 50 { 0.0 }              // half-bin leftover: very reusable
        else if pr >= 25 && pr < 50 { 1.0 }   // quarter-to-half: decent
        else if pr >= 10 { 0.5 }              // marginal
        else { -2.0 };                        // dead space: penalize implicitly via bonus subtraction

    // Reward bins whose leftover stays in a reusable class
    score -= usable * 4.0;

    // Integer-division harmony: leftover divisible into halves/quarters of capacity is good
    if pr > 0 && (bin_capacity % pr == 0 || pr % 10 == 0) {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr {
            score -= 3.0 + (pr as f64 - next_item_size as f64).min(10.0) * 0.2;
        } else {
            // next item cannot use this leftover: slight penalty for large leftovers
            score += (pr / 20.0).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: make it unattractive unless leftover landscape is bad.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified when existing bins would leave dead space
        // or when the stream is early and many items are expected.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let dead_space_pressure = ((mean_residual - post) / cap).clamp(0.0, 1.0);
        score += 15.0 - 6.0 * progress - 10.0 * dead_space_pressure;
    }

    // Prefer filling bins that are already committed (larger current fill)
    score -= (cap - bin_residual as f64) * 0.05;

    // Mild preference for concentrating items when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are penalized heavily. Threshold scales with typical item size.
    let dead_threshold = 10.0_f64.max(next_item_size as f64 * 0.6);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 25.0 + (dead_threshold - post_residual as f64) * 2.0;
    }

    // Perfect or near-perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Fit tightness: reward small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64 / post_residual.max(1) as f64) * 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 12.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item won't fit here: this residual becomes dead space for lookahead.
        score += 10.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + pressure * 3.0;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins with below-average residual (fill the emptiest usable bins first
    // among fitting ones, but avoid wasting near-empty bins on tiny items).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor placements leaving near-zero residual.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a chained perfect fit — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 180.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 90.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Dead space: next item cannot use the leftover — penalize proportionally.
            score += (post_residual as f64) * 1.5;
        }
    }

    // Relative-to-mean coupling: a bin with residual well below the mean is
    // already "tight"; placing here consolidates waste. Reward that.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res_f - mean_residual) / mean_residual;
        score += rel * 25.0; // below-mean residual => negative contribution => favored
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 40.0;
    }

    // Penalize leaving large unusable chunks (dead space heuristic):
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // small scraps are often useless; better to fill now
    }

    // Early stream: be slightly more willing to open new bins to build a
    // diverse residual pool; late stream: consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if all open bins fit poorly.
        score += 15.0 + 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score += 10.0; // discourage abandoning the sole fitting bin
        }
    }

    // Mild penalty for spreading across many bins when consolidation possible.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size
    if item_size > 0 {
        score -= 0.6 * (item_size as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize very small post residuals (dead space) less than moderate ones,
    // but reward exact-ish fits strongly
    if post_residual < 10 {
        score -= 15.0;
    } else if post_residual > 50 {
        score += 8.0; // leaving a large hole is wasteful
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 12.0;
        // extra reward for near-exact chain fit
        let chain_gap = post_residual as f64 - next_item_size as f64;
        score -= 5.0 * (1.0 - chain_gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here; slightly penalize hoarding space it needs elsewhere
        score += 3.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is penalized more when many
    // bins are open and mean residual is large (fragmentation waste)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln().max(1.0);
        score += 25.0 + 10.0 * waste_pressure + 5.0 * (1.0 - progress);
        // but if item is large and no tight fit exists, new bin is fine
        if item_size >= 50 && fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    // Mild preference for fuller bins among many open bins
    score -= 2.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Time horizon: late in stream, prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with quadratic sharpening
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth non-linear coupling: as stream progresses, tighten fit preference more aggressively
    let tighten = 1.0 + 2.0 * progress * progress;
    score *= tighten;

    // Reward tight fits (small post residual) more when many bins are open
    let crowding = (open_bins_count as f64).ln() + 1.0;
    score -= 15.0 * crowding * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Penalize when this bin's residual is far above the mean (poorly utilized bin)
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead coupling: smooth interaction between post-residual and next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let nx_norm = nx / cap;
        // If next item would fit in post-residual, reward
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= 10.0 * fits_next * nx_norm * (1.0 - pr_norm);
        // Smooth penalty: large post residual that cannot host next item is dead space
        score += 8.0 * pr_norm * nx_norm;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: make empty bin attractive only for large items / early progress
    if bin_residual == bin_capacity {
        let item_norm = item_size as f64 / cap;
        score = cap * (0.5 + 0.5 * progress) + 30.0 * (1.0 - item_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: modulo classes relative to capacity ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Dead-space penalty: residuals that no typical item (1..=100) can pair with.
    if post_residual > 0 {
        // Class A: residual too small to hold the smallest plausible item chunk.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post) / 10.0;
        }
        // Class B: residual in awkward mid-band (e.g. 41..49, 51..59) — few items land there.
        let m = post_residual % 10;
        if m >= 1 && m <= 4 && post_residual > 20 {
            score += 8.0 + 2.0 * (4 - m) as f64;
        }
        // Perfect harmonic fits: post_residual divisible by common item granularities.
        if post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0 {
            score -= 12.0;
        } else if post_residual % 10 == 0 {
            score -= 6.0;
        }
    } else {
        // Perfect fill — strongly reward closing the bin exactly.
        score -= 100.0;
    }

    // --- Lookahead coupling: does next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: reward, scaled by tightness of chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / cap);
            // Bonus if chain leaves another harmonic residual.
            let chain_post = post_residual - next_item_size;
            if chain_post % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot follow here: penalize proportionally to overflow gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / cap).min(1.0);
        }
    }

    // --- Capacity fraction thresholds ---
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    if fill_frac >= 0.75 {
        score -= 10.0; // near-full bins: prefer to keep topping them off
    } else if fill_frac <= 0.25 && post_residual > 0 {
        score += 5.0; // barely-touched bins: avoid dumping small items too early
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0; // only fitting bin: strongly prefer using it over a new bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new bin: base cost of opening; make it attractive only when
        // current item would leave a large dead residual in every open bin.
        score = cap * 0.55 + post_residual as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // fresh bin chains well with lookahead
        }
        if fitting_bins_count == 0 {
            score -= cap; // no open bin fits: new bin is mandatory
        }
    }

    // --- Stream progression: mild pressure to consolidate as stream ends ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // --- Global residual dispersion: prefer bins below mean residual (tighter) ---
    score -= 3.0 * (mean_residual - post).max(0.0) / cap;

    // --- Open-bin count pressure: discourage bin proliferation ---
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer bins that leave large usable residual (low score for large post_residual)
    let mut score = post;

    // Dead-space penalty: residuals that are too small to fit any plausible future item
    // (items are 1..100, but small gaps < 10 are almost certainly dead space; taper up to ~30)
    let dead_threshold = 30.0;
    if post > 0.0 && post < dead_threshold {
        // sharply penalize unusable slivers: quadratic ramp peaking near zero
        let severity = (dead_threshold - post) / dead_threshold; // 0..1
        score += 40.0 * severity * severity;
    }
    // Perfect fit: zero dead space gets strong reward
    if post == 0.0 {
        score -= 60.0;
    }

    // Tightness reward: fraction of the bin consumed by this item
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: empty bin should only win when the item is large
    // or no open bin offers a decent fit. Penalize opening a new bin generally,
    // but reduce penalty for big items that would leave a useful residual anyway.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / cap;
        let mut new_bin_penalty = 55.0;
        // large items justify fresh bins; also if next item is large, a fresh bin is fine
        if fill_frac > 0.5 {
            new_bin_penalty -= 20.0 * (fill_frac - 0.5);
        }
        if next_item_size as f64 > 0.6 * cap {
            new_bin_penalty -= 15.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += 20.0 * progress;
        score += new_bin_penalty;
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let next_fit_quality = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap);
        score -= 20.0 * next_fit_quality;
    }
    // If next item would be blocked by a sliver, penalize slightly
    else if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post {
        score += 8.0;
    }

    // Mean residual coupling: if open bins are already fragmented (low mean residual),
    // prefer placements that consolidate (tight fits)
    if mean_residual > 0.0 {
        let frag = 1.0 - (mean_residual / cap);
        score += 10.0 * frag * (post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        // Extra bonus for exact match.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize post_residual too small for next item but nonzero (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 20.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: prefer tightest fit.
        score += 10.0;
    }

    // Prefer bins with residual already below mean (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins fit well.
    if bin_residual == bin_capacity && post_residual > 0 {
        score += 12.0;
        // Allow new bin early in stream or when open bins are crowded.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 4 && progress > 0.2 {
            score += 8.0;
        }
    }

    // Slight preference for fuller bins overall.
    score -= item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space.
    let pr = post_residual as f64;
    score -= 60.0 * ((1.0 - pr / bin_capacity as f64).powi(6));

    // Exact-ish fit: strong reward when post_residual is tiny.
    if post_residual <= 3 && post_residual > 0 {
        score -= 45.0;
    }
    if post_residual == 0 {
        score -= 80.0;
    }

    // Dead-space penalty: leftover space too small for the smallest plausible item (1..100 unknown, assume >=10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 35.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasting residual that is close to next item size.
            let gap = (post_residual as f64 - nxt).abs();
            if gap < 8.0 {
                score += 18.0 * (1.0 - gap / 8.0);
            }
        }
        // If next item is huge, prefer conserving large residuals.
        if nxt > 60.0 && post_residual > nxt {
            score -= 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        // Base mild penalty so a decent existing fit beats a new bin.
        score += 30.0;
        // But if existing bins are fragmented (high mean residual spread vs this fit), open new bin.
        let tightness = 1.0 - (item_size as f64 / bin_residual as f64);
        if mean_residual < item_size as f64 * 1.2 {
            score -= 40.0; // open bins are too full; new bin is good
        }
        if item_size > 70 {
            score -= 20.0; // big items deserve fresh bins
        }
        let _ = tightness;
    }

    // Time horizon: early in the stream, be conservative with bins (favor filling existing);
    // late in the stream, allow more aggressive new-bin usage since tail waste matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress;

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - progress);

    // Prefer bins whose residual is close to the item (relative fit quality).
    let rel_fit = item_size as f64 / bin_residual as f64;
    score -= 20.0 * rel_fit;

    // Mean residual anchor: bins below mean residual are "denser", prefer them.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item / cap;

    // Smooth polynomial core: quadratic waste penalty
    let mut score = norm_post * norm_post * 60.0 + norm_post * 20.0;

    // Non-linear coupling of waste with stream progress:
    // late in the stream, dead space hurts more (compounding term)
    let prog_sq = progress * progress;
    score += prog_sq * norm_post * 40.0;

    // Coupling with item size: large items prefer tight fits, smooth cubic in norm_item
    score -= norm_item * norm_item * norm_item * 25.0 * (1.0 - norm_post);

    // Mean residual interaction: placing into a bin near the mean residual is mildly favored
    let mean_norm = mean_residual / cap;
    score -= (1.0 - (norm_post - mean_norm).abs()) * 5.0;

    // Last-chance bonus (smooth, not piecewise): fewer fitting bins => stronger reward
    let fit_den = (fitting_bins_count.max(1) as f64).powf(1.5);
    score -= 15.0 / fit_den;

    // Lookahead coupling: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let compat = 1.0 - ((norm_post - nxt).abs() / cap).min(1.0);
        score -= compat * compat * 12.0;
    }

    // Mild pressure against bin proliferation early on
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // New-bin candidate: penalize smoothly unless waste would be very low
    if bin_residual == bin_capacity {
        score += 30.0 - 25.0 * (1.0 - norm_item).powi(3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction bands. Small leftovers (< capacity/4) are "dead space"
    // classes that are hard to reuse -> penalize.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual <= quarter / 2 {
        // Tiny sliver: nearly dead space, penalize heavily.
        score += 60.0;
    } else if post_residual <= quarter {
        score += 25.0;
    } else if post_residual <= half {
        score -= 5.0;
    } else {
        // Large leftover: still very reusable.
        score -= 15.0;
    }

    // Modulo arithmetic on post_residual: leftovers divisible by common
    // item-size classes (e.g. multiples of 10, or of half/quarter) are
    // more likely to be exactly filled later.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this bin becomes a perfect two-step chain -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves another leftover: classify that
            // second-order leftover harmonically.
            let second = post_residual - next_item_size;
            if second % 10 == 0 {
                score -= 12.0;
            }
            if second <= quarter / 2 {
                score += 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Next item cannot follow in this bin: mild penalty scaled
            // by how far off it is (integer-division gap).
            let gap_classes = (next_item_size - post_residual) / 10;
            score += gap_classes as f64 * 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it
    // over opening a new bin (unless post_residual is a dead sliver).
    if fitting_bins_count == 1 && post_residual > quarter / 2 {
        score -= 40.0;
    }

    // Early in the stream, encourage keeping bins tight (low post_residual)
    // to preserve flexibility; late in the stream, favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Prefer bins whose residual is below the mean (tight bins close first),
    // leaving larger-residual bins open for future items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when no open bin fits or when the
    // current item is huge relative to capacity (harmonic class > 3/4).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if item_size * 4 > bin_capacity * 3 || fitting_bins_count == 0 {
            score -= 30.0; // open a fresh bin for big items / no alternatives
        } else {
            score += 80.0; // discourage wasting a fresh bin on small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste. Penalize the "unusable gap"
    // band harshly, on a rising slope as it approaches fullness.
    let min_item = 10.0f64.min(bin_capacity as f64);
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 60.0 * (1.0 - (post_residual as f64) / min_item);
    }

    // Unusable relative to the *next* item: a gap that can't host the lookahead
    // is likely stranded unless something smaller arrives.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Reward tight fits generally (post_residual already small lowers score).
        let tightness = 1.0 - (post_residual as f64) / bin_capacity as f64;
        score -= 8.0 * tightness;
    }

    // Open-bin pressure: prefer consolidating into existing bins; opening new
    // bins is costly, so make the empty-bin candidate less attractive as
    // open_bins_count grows relative to a soft target.
    let soft_target = 3.0 + (step_index as f64 / total_items.max(1) as f64) * 5.0;
    let pressure = ((open_bins_count as f64 - soft_target).max(0.0)) * 6.0;
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, using it avoids a
    // new bin entirely.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Slight bias toward bins whose residual is near the mean (balanced use).
    score += 0.3 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward perfect or near-perfect
    // matching of the leftover space to the NEXT item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward proportionally to tightness of fit.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize dead space that nothing can use.
            score += 15.0 + 0.5 * diff;
        }
        // Small extra nudge when the next item would leave a tiny residue again.
        let post2 = post_residual as i64 - next_item_size as i64;
        if post2 > 0 && post2 < 10 {
            score -= 10.0;
        }
    }

    // Penalize residuals far below the mean (fragmenting small bins).
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted late in the stream
        // (fewer future chances to amortize it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 70.0 + 30.0 * (1.0 - progress);
        // If the next item is large, a fresh bin is more useful.
        if next_item_size > item_size {
            score -= 10.0;
        }
        // If many bins already fit the item, opening another is wasteful.
        if fitting_bins_count > 0 {
            score += 20.0 * fitting_bins_count as f64;
        }
    }

    // Prefer filling bins with larger residual capacity slightly less
    // (keeps big bins flexible), small bonus for tight fills.
    if post_residual < 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below
    // the minimum item size (1..=100 unknown dist, assume ~10) is wasted.
    let min_item: f64 = 10.0;
    if (post_residual as f64) < min_item && bin_residual != bin_capacity {
        score -= 50.0; // near-perfect fill
    } else {
        // penalize residual that is slightly above the smallest plausible item
        let waste = (post_residual as f64 - min_item).max(0.0);
        score += 0.15 * waste;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward;
    // if next item is large and post_residual is tiny-but-unusable, mild penalty.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx as u32) <= post_residual {
            // chain fit: reward proportional to how well next item also fits
            let chain_left = post_residual as f64 - nx;
            score -= 8.0 + 0.2 * chain_left.max(0.0);
        } else {
            score += 0.05 * (nx - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Global state: many open bins with slack -> prefer consolidation.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.5));
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be more willing to open new bins
    // (keep bins clean); late in stream, squeeze everything.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize late in stream, reward early
        score += 20.0 * t - 10.0 * (1.0 - t);
        if post_residual as f64 >= 0.5 * bin_capacity as f64 {
            score -= 5.0; // a fresh bin is fine early
        }
    } else {
        score -= 5.0 * t; // favor existing bins more as stream progresses
    }

    // Mild preference for bins already below mean residual (balance load)
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Base: prefer minimal post residual (tight packing)
    let mut score = post;

    // Non-linear reward for tight fits, amplified as the stream progresses
    let tightness = 1.0 - (post / cap);
    score -= 22.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space that is too small to hold the next item (smooth coupling)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let unusable = ((ns - post) / cap).max(0.0);
        score += 30.0 * (unusable * (1.0 + progress));
        // Reward post residual that still accommodates the lookahead item
        let headroom = (post / ns).min(1.0);
        score -= 8.0 * headroom * headroom;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty when bin residual deviates from the mean (encourage balanced residuals)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Late-stream: discourage opening new bins (smooth quadratic in progress)
    score += 12.0 * progress * progress * (post / cap);

    // Slight penalty for very large items leaving huge residuals (wasted space coupling)
    score += 5.0 * fit * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into 4 octants.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual as f64;

    // Reward leaving residuals in "usable" harmonic classes (multiples of quarter).
    let class_penalty = match post_residual {
        0 => -8.0,                       // perfect closure
        r if r % quarter == 0 => -3.0,   // aligned residual, easy to refill
        r if r < quarter => 6.0,         // tiny sliver: dead space
        r if r % (quarter / 2) == 0 => -1.5,
        _ => 0.0,
    };
    score += class_penalty;

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional fit quality (small leftover after next item).
            let after_next = post_residual - next_item_size;
            score -= 4.0 * (after_next as f64 / bin_capacity as f64);
            if after_next == 0 { score -= 5.0; }
        } else {
            // Next item cannot use this bin's leftover: penalize.
            score += 3.0 + 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are fragmented (mean residual too small to be useful).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.25 {
            score -= 2.0 * (1.0 - progress); // early stream: fresh bins OK
        } else {
            score += 6.0 + 4.0 * fragmentation; // keep using open space
        }
        // Never prefer a new bin when an existing bin closes perfectly.
        if post_residual == 0 { score += 20.0; }
    }

    // Mild pressure against hoarding many open bins.
    score += 0.02 * open_bins_count as f64;

    // Integer-division threshold: residuals in (half, 3*quarter] are prime refill targets.
    if post_residual > half && post_residual <= 3 * quarter {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 120.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Last fitting bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 2.0;

    // Prefer bins whose residual deviates favorably from the mean (consolidate).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if the next item would fit exactly in the post residual, reward;
    // if post residual is too small for the next item, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // New-bin candidate: only attractive when current fit would create dead space.
    if bin_residual == bin_capacity {
        score = 40.0 + (open_bins_count as f64) * 0.5;
        if post_residual == 0 || post_residual >= 30 {
            score -= 35.0;
        }
        if fitting_bins_count == 1 {
            score += 80.0; // never open a new bin when this is the last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact match with the next item (perfect 2-step fill)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // leftover after placing the next item: penalize proportionally
            let leftover = post_residual - next_item_size;
            score += leftover as f64 * 2.0;
            // small reward if next item fits at all
            score -= 50.0;
        } else {
            // next item won't fit here: penalize dead space growth
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Reward tight fits relative to current item
    if post_residual < item_size / 2 {
        score -= 25.0;
    }

    // Penalize residuals far above the mean residual (wasteful bin)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Slight preference for keeping the number of open bins low late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.1;

    // Mild nudge to prefer new bins only when residual would be tiny waste elsewhere
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize small-but-not-zero dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit reward, stronger when snug for the next item too.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasting residual that could
            // have been saved for a better match.
            score += 3.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive only if no
    // decently fitting open bin exists or open bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_fill_pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin when existing residuals are small (bins nearly full)
        // and there are many alternatives; penalize opening bins early.
        score += 10.0 * avg_fill_pressure;
        score += (1.0 - progress) * 5.0;
        score -= (fitting_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 25.0; // must open a new bin anyway
        }
    } else {
        // Prefer filling bins that are already more depleted relative to mean.
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * dev;
    }

    // Mild preference to spread across bins when many are open (balance load)
    if open_bins_count > 1 && bin_residual < bin_capacity {
        score -= 0.5 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Late-stream urgency: as the stream nears its end, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Normalized post-residual and its polynomial coupling with progress
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 30.0 * norm_pr * (1.0 - norm_pr) * progress;

    // Penalize dead space that next item cannot use (smooth quadratic)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 0.8 * gap * gap / cap;
    }

    // Last-chance bonus when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when bin residual is far from mean residual (smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Encourage consolidating into bins when many bins open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "reusable" residue classes (divisible by common item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are clean multiples of likely item sizes (1..=100 stream)
        let mut harmony: f64 = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50] {
            if pr % m == 0 {
                harmony += 12.0;
            }
        }
        // Exact-fit class reward scaled by how large the reusable chunk is
        score -= harmony * (pr as f64 / bin_capacity as f64);
    } else {
        // Perfect fit: strongest possible reward
        score -= 60.0;
    }

    // Penalize tiny dead space (waste) in non-harmonic classes
    if pr > 0 && pr < 10 {
        score += 35.0;
    }

    // Integer-division threshold: post_residual class via pr / 10
    let class = pr / 10;
    match class {
        0 => score += 20.0,          // nearly-full bin, small but usable leftover
        1 | 2 => score -= 8.0,       // sweet spot leftovers (10..=29)
        3 | 4 => score -= 4.0,       // decent leftovers
        _ => score += 2.0,           // large leftover means item was small here
    }

