    // Lookahead: graded reward for leaving a residual the next item can use.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 36.0;
        } else if gap <= 4 {
            score -= 20.0;
        } else if gap <= 12 {
            score -= 9.0;
        } else if gap <= 24 {
            score -= 3.0;
        }
        // Two-item lookahead coupling.
        let after_next = gap;
        if after_next >= next_item_size {
            score -= 9.0;
        } else if after_next > 0 && after_next <= 6 {
            score -= 5.0;
        } else if after_next <= 10 {
            score -= 2.0;
        }
        // Residual just above the dead threshold: next item fits tightly.
        if (after_next as f64) <= dead_threshold * 0.3 && fitting_bins_count >= 1 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        let waste_ratio = (post_residual as f64) / (next_item_size as f64).max(1.0);
        let soft = if post_residual <= 3 { 0.35 } else { 1.0 };
        score += (8.0 + waste_ratio * 12.0) * soft;
        // Near-miss dead space is the most wasteful kind.
        let miss = next_item_size - post_residual;
        if miss <= 3 {
            score += 14.0;
        } else if miss <= 8 {
            score += 7.0;
        } else if (post_residual as f64) > dead_threshold * 0.5 {
            score += 5.0;
        }
    }

    // Consolidation pressure: prefer bins whose residual sits below the mean.
    if fitting_bins_count > 2 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.4 {
