    }
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Exact-mean fit: bin residual matches the item size closely — strong consolidation signal.
    if fitting_bins_count > 0 && (mean_residual - item_size as f64).abs() < 1.5 && open_bins_count > 1 {
