        if load >= 0.25 && next_item_size > 0 && post_residual >= next_item_size {
            score += 13.0;
        }
        if fitting_bins_count == 1 {
            score += 90.0;
        }
        if load < 0.35 && fitting_bins_count >= 2 {
            score += 17.0;
        }
        if load < 0.6 && fitting_bins_count >= 4 {
            score += 9.0;
        }
        if fitting_bins_count > 0 && progress > 0.7 {
            score += 6.0 * progress;
        }
        if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
            score += 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 0 {
            score += 24.0;
        }
        // Estimate whether a fresh bin would be over-filled relative to mean residual slack.
        if fitting_bins_count > 0 {
            let best_possible_fill = item_size as f64 / (item_size as f64 + mean_residual.min(bin_capacity as f64).max(1.0));
            if best_possible_fill > 0.85 {
                score += 13.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
