    // Adaptive dead-space threshold tied to lookahead item size.
    let dead_threshold = 10.0_f64.max((next_item_size as f64 * 0.6).min(50.0));
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 24.0 + (dead_threshold - post_residual as f64) * 2.8;
    }

    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    } else if post_residual <= 4 {
        // Tiny gap is nearly perfect: reward closing it out.
        score -= 28.0;
    }

    // Reward tight fills, superlinear for very full placements.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;
    if fill_ratio > 0.75 {
        score -= (fill_ratio - 0.75) * 70.0;
    }

    // Last fitting bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 64.0;
    }

    // Lookahead: graded reward for leaving a residual the next item can use.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 36.0;
        } else if gap <= 4 {
            score -= 20.0;
        } else if gap <= 12 {
            score -= 9.0;
        } else if gap <= 24 {
            score -= 3.0;
        }
        // Two-item lookahead coupling.
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size {
            score -= 9.0;
        } else if after_next > 0 && after_next <= 6 {
            score -= 5.0;
        } else if after_next <= 10 {
            score -= 2.0;
        }
        if after_next == 2 * next_item_size {
            score -= 6.0;
        }
        // Residual close to hosting next item exactly with tight slack.
        if (after_next as f64) <= dead_threshold * 0.3 && fitting_bins_count >= 1 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        let waste_ratio = (post_residual as f64) / (next_item_size as f64).max(1.0);
        let soft = if post_residual <= 3 { 0.35 } else { 1.0 };
        score += (8.0 + waste_ratio * 12.0) * soft;
        // Near-miss dead space is the most wasteful kind.
        let miss = next_item_size - post_residual;
        if miss <= 3 {
            score += 14.0;
        } else if miss <= 8 {
            score += 7.0;
        }
        // Stranded tiny dead space relative to capacity.
        let stranded = (post_residual as f64) / bin_capacity as f64;
        if stranded < 0.08 && miss > 8 {
            score += 10.0 * (0.08 - stranded) * 100.0;
        }
    }

    // Consolidation pressure: prefer bins whose residual sits below the mean.
    if fitting_bins_count > 2 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.4 {
        score -= 6.0;
    }
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream pressure: favor compacting into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.5 && bin_residual < bin_capacity {
        score -= progress * 10.0;
    }
    // Endgame: favor tight fits harder when few items remain.
    if progress > 0.85 && bin_residual < bin_capacity {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 8.0 * progress;
    }

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE
        let load = item_size as f64 / bin_capacity as f64;
        if load < 0.25 && fitting_bins_count > 0 {
            score -= 6.0;
        } else {
            score += 5.0 * load;
        }
        if post_residual == 0 || post_residual >= 28 {
            score -= 36.0;
        }
        if post_residual > 0 && post_residual >= 28 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Prefer a fresh bin when the next item is large and would be stranded.
        if next_item_size >= 45 && post_residual < next_item_size && post_residual > 0 {
            score -= 20.0;
        }
        if load >= 0.25 && next_item_size > 0 && post_residual >= next_item_size {
            score += 13.0;
        }
        if fitting_bins_count == 1 {
            score += 90.0;
        }
        if load < 0.35 && fitting_bins_count >= 2 {
            score += 17.0;
        }
        if load < 0.6 && fitting_bins_count >= 4 {
            score += 9.0;
        }
        if fitting_bins_count > 0 && progress > 0.7 {
            score += 6.0 * progress;
        }
        if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
            score += 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 0 {
            score += 24.0;
