            if best_possible_fill > 0.85 {
                score += 13.0;
            }
        }
        // Strong pull: an existing bin whose residual nearly matches the item.
        if fitting_bins_count > 0 && (mean_residual - item_size as f64).abs() < 1.5 && open_bins_count > 1 {
            score += 30.0;
        }
        // Avoid a fresh bin whose residual is awkward: too small for the next
        // item but too big to be negligible, when good fits exist.
        if post_residual > 0 && post_residual < next_item_size && post_residual >= 12
            && next_item_size >= 30 && fitting_bins_count >= 2 {
            score += 9.0;
        }
        // A fresh bin is attractive when its leftover can be split by the
        // mean open-bin residual (matches aggregate demand shape).
        if post_residual > 0 && mean_residual > 1.0 {
            let chunks = post_residual as f64 / mean_residual;
            if (chunks - chunks.round()).abs() < 0.15 && chunks.round() >= 1.0 {
                score -= 4.0 * chunks.min(3.0);
            }
        }
        // Late in the stream, avoid opening bins whose leftover cannot be
        // closed out by remaining demand.
        if progress > 0.75 && post_residual > 0 && (post_residual as f64) > mean_residual * 1.5 + 4.0 {
            score += 9.0 * (progress - 0.75) * 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 2 {
            score -= 8.0;
        }
        if post_residual > 0 && post_residual < next_item_size && post_residual >= 20 && fitting_bins_count >= 3 {
            score += 12.0;
        }
        if post_residual > 0 && post_residual < 28 && next_item_size > 0 && next_item_size - post_residual > 12 {
            score += 7.0 * (1.0 - progress);
        }
        if open_bins_count > 2 && (mean_residual as u32) >= item_size + 6 && fitting_bins_count >= 2 && load < 0.5 {
            score += 10.0;
        }
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 * 1.3 && open_bins_count > 1 {
            score += 6.0 * (mean_residual / bin_capacity as f64).min(0.5) * 10.0;
        }
    } else {
        // EXISTING-BIN CANDIDATE refinements.
        if post_residual > 0 && post_residual <= 8 && next_item_size > post_residual {
            score -= 11.0;
        }
        let res_ratio = post_residual as f64 / bin_capacity as f64;
        if res_ratio < 0.1 {
            score -= 5.0;
        }
        if post_residual == 0 && next_item_size > 0 && fitting_bins_count >= 2 {
            score -= 6.0;
        }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 6 {
            score += 6.0;
        }
        if post_residual >= 2 * next_item_size && next_item_size > 0 {
            score -= 5.0;
        }
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.55 && fitting_bins_count > 0 && post_residual < next_item_size {
            score += 10.0 * (dead_ratio - 0.55);
        }
        // NEW: mid-stream dead-space pressure, stronger early where
        // consolidation opportunities still exist.
        if dead_ratio > 0.4 && post_residual < next_item_size {
            score += (dead_ratio - 0.4) * 22.0 * (1.0 - progress);
        }
        if post_residual > 0 {
            let dev = ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();
            if dev < 0.05 {
                score -= 4.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual as f64 <= mean_residual * 1.2 {
                score -= 3.0;
            }
            // Prefer residuals divisible by the next item size (allows
            // repeated identical fits, tightening consolidation).
            if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
                score -= 3.5;
            }
            if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 {
                score -= 2.5;
            }
        }
        if fitting_bins_count >= 2 && res_ratio < 0.15 && post_residual > 0 {
            score -= 2.0;
        }
        if progress > 0.6 {
            if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 6 {
                score -= 4.0 * (progress - 0.6) * 10.0;
            }
            if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size * 3 {
                score += 2.0 * (progress - 0.6) * 5.0;
            }
        }
        if fitting_bins_count >= 3 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
        // When few bins fit and this one leaves a small orphan, nudge
        // selection toward bins whose leftover is large enough to matter later.
        if fitting_bins_count <= 2 && post_residual > 0 && post_residual < next_item_size && (post_residual as f64) < mean_residual * 0.4 {
            score += 4.0;
        }
    }

    score
}

