pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Adaptive dead-space threshold tied to lookahead item size.
    let dead_threshold = 10.0_f64.max((next_item_size as f64 * 0.6).min(50.0));
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 24.0 + (dead_threshold - post_residual as f64) * 2.8;
    }

    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 58.0;
    } else if post_residual <= 4 {
        // Tiny gap is nearly perfect: reward closing it out.
        score -= 26.0;
    }

    // Reward tight fits relative to bin capacity, superlinear for very full placements.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 32.0;
    if fill_ratio > 0.75 {
        score -= (fill_ratio - 0.75) * 70.0;
    }

    // Last fitting bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Lookahead: graded reward for leaving a residual the next item can use.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 34.0;
        } else if gap <= 4 {
            score -= 20.0;
        } else if gap <= 12 {
            score -= 9.0;
        } else if gap <= 24 {
            score -= 3.0;
        }
        // Two-item lookahead coupling: reward residuals that can host the next item twice.
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size {
            score -= 8.0;
        } else if after_next > 0 && after_next <= 6 {
            score -= 5.0;
        } else if after_next <= 10 {
            score -= 2.0;
        }
        if next_item_size > 0 && after_next >= 2 * next_item_size {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        let waste_ratio = (post_residual as f64) / (next_item_size as f64).max(1.0);
        let soft = if post_residual <= 3 { 0.35 } else { 1.0 };
        score += (8.0 + waste_ratio * 12.0) * soft;
        let miss = next_item_size - post_residual;
        if miss <= 3 {
            score += 14.0;
        } else if miss <= 8 {
            score += 7.0;
        }
        let stranded = (post_residual as f64) / bin_capacity as f64;
        if stranded < 0.08 && miss > 8 {
            score += 10.0 * (0.08 - stranded);
        }
