        score += 24.0 + (dead_threshold - post_residual as f64) * 2.8;
    }

    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 4 {
        score -= 28.0;
    }

    // Reward tight fills relative to capacity, superlinear for very full placements.
