            score -= 9.0;
        } else if after_next > 0 && after_next <= 6 {
            score -= 5.0;
        } else if after_next <= 10 {
            score -= 2.0;
        }
        if after_next == 2 * next_item_size {
            score -= 6.0;
        }
        if post_residual - next_item_size <= 2 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        let waste_ratio = (post_residual as f64) / (next_item_size as f64).max(1.0);
