        score += (8.0 + waste_ratio * 12.0) * soft;
        // Graded penalty when the next item just barely misses fitting.
        let miss = next_item_size - post_residual;
        if miss <= 3 {
            score += 14.0;
        } else if miss <= 8 {
            score += 7.0;
        }
        let stranded = (post_residual as f64) / bin_capacity as f64;
        if stranded < 0.08 && miss > 8 {
            score += 10.0 * (0.08 - stranded);
        }
        if miss > 8 && miss <= 16 && post_residual >= 10 {
            score += 4.0;
        }
        if miss > 16 && miss <= 24 && post_residual >= 14 {
            score += 2.5;
        }
