    if progress > 0.5 && bin_residual < bin_capacity {
        score -= progress * 10.0;
    }
    if progress > 0.85 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 8.0 * progress;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let load = item_size as f64 / bin_capacity as f64;
        if load < 0.25 && fitting_bins_count > 0 {
            score -= 6.0;
        } else {
            score += 5.0 * load;
        }
        if post_residual == 0 || post_residual >= 28 {
            score -= 36.0;
        }
        if post_residual > 0 && post_residual >= 28 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Prefer a fresh bin when the next item is large and would be stranded.
        if next_item_size >= 45 && post_residual < next_item_size && post_residual > 0 {
            score -= 20.0;
        }
        // Avoid opening a new bin when an existing bin leaves a usable residual.
        if load >= 0.25 && next_item_size > 0 && post_residual >= next_item_size {
            score += 13.0;
        }
        if fitting_bins_count == 1 {
            score += 90.0;
        }
        if load < 0.35 && fitting_bins_count >= 2 {
            score += 17.0;
        }
        if load < 0.6 && fitting_bins_count >= 4 {
            score += 9.0;
        }
        if fitting_bins_count > 0 && progress > 0.7 {
            score += 6.0 * progress;
        }
        if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
            score += 8.0;
        }
