            score += 24.0;
        }
        // Mean-residual match: an existing bin can absorb this item almost exactly.
        if fitting_bins_count > 0 && (mean_residual - item_size as f64).abs() < 1.5 && open_bins_count > 1 {
            score += 30.0;
        }
        if post_residual > 0 && post_residual < next_item_size && post_residual >= 20 && fitting_bins_count >= 3 {
