        if res_ratio < 0.1 {
            score -= 5.0;
        }
        if post_residual == 0 && next_item_size > 0 && fitting_bins_count >= 2 {
            score -= 6.0;
        }
        if post_residual > 0 && next_item_size > post_residual && (post_residual as f64) > dead_threshold * 0.5 {
            score += 5.0;
        }
        if post_residual >= 2 * next_item_size && next_item_size > 0 {
            score -= 5.0;
        }
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.55 && fitting_bins_count > 0 && post_residual < next_item_size {
            score += 10.0 * (dead_ratio - 0.55);
        }
        if dead_ratio > 0.4 && post_residual < next_item_size {
            score += (dead_ratio - 0.4) * 22.0 * (1.0 - progress);
        }
        if post_residual > 0 {
            let dev = ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();
            if dev < 0.05 {
                score -= 4.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual as f64 <= mean_residual * 1.2 {
                score -= 3.0;
            }
            if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
                score -= 3.5;
            }
        }
        if fitting_bins_count >= 2 && res_ratio < 0.15 && post_residual > 0 {
            score -= 2.0;
        }
        if progress > 0.6 {
            let gap = if next_item_size > 0 && post_residual >= next_item_size { post_residual - next_item_size } else { u32::MAX };
            if gap != u32::MAX && gap <= 6 {
                score -= 4.0 * (progress - 0.6) * 10.0;
            }
            if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size * 3 {
                score += 2.0 * (progress - 0.6) * 5.0;
            }
        }
        if fitting_bins_count >= 3 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 && post_residual < next_item_size && (post_residual as f64) < mean_residual * 0.4 {
            score += 4.0;
        }
        if dead_ratio > 0.6 && post_residual > 0 && post_residual < 10 && fitting_bins_count >= 1 {
            score += 6.0 * (dead_ratio - 0.6) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that the next item can still fit into.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bins are heavily fragmented.
    if bin_residual == bin_capacity {
        score += 30.0 + (mean_residual / 100.0) * -20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match between post_residual and next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= 60.0 * (1.0 - diff as f64 / 40.0).max(0.0);
        // next item fits exactly -> strong reward
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // next item fits but leaves dead space -> mild penalty
        if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0;
        }
        // next item cannot fit in this residual -> dead space penalty
        if post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        // last item: minimize waste directly
        score -= 30.0;
    }

    // prefer bins tighter than the average residual (good fits)
    score -= (mean_residual - post_residual as f64) * 2.0;

    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        // but allow new bin if item is huge and would leave tiny residual anywhere
        if item_size >= 80 {
            score -= 20.0;
        }
    }

    // progression: as stream advances, be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good; penalize large dead space nonlinearly.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins whose residual is close to the item size (perfect fit reward).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 10.0 * (1.0 - fit_gap / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, reward heavily;
    // if post residual is too small for the next item (dead space), penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // post_residual becomes dead space unless future small items arrive
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Time horizon: early in the stream, be more conservative (favor new bins
    // for large items to keep flexibility); late, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling
    // underutilized bins rather than opening new ones.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: make an empty bin attractive only when the item is large
    // (few future fits likely) and there are few open bins; otherwise discourage.
    if bin_residual == bin_capacity {
        score += 15.0 - 0.2 * item_size as f64;
        if open_bins_count == 0 {
            score -= 50.0; // must open the first bin
        }
    }

    // Mild preference for bins with residuals that are "awkward" (prime-ish gaps)
    // to consolidate fragmentation.
    if bin_residual % 10 != 0 && post_residual > 0 && post_residual < 10 {
        score -= 4.0; // near-perfect fill, small leftover is acceptable
    }

    score
}

