pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual)
    let mut score = post;

    // Smooth non-linear polynomial coupling with stream progress:
    // early on, waste is cheap (many items left to fill gaps);
    // late, waste becomes exponentially more costly.
    let waste_penalty = norm_post * norm_post * (1.0 + 3.0 * progress * progress);
    score += waste_penalty * cap * 0.5;

    // Dead-space term: residuals too small for typical future items are penalized
    // smoothly via a bell-shaped polynomial around the "useful" zone.
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (post - next).abs();
        let gap_norm = gap / cap;
        score += gap_norm * gap_norm * cap * (0.5 + progress);
        // Reward bins whose post residual exactly accommodates the lookahead item
        if post >= next {
            score -= (post - next) * 0.25;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly discourage opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * (0.3 + 0.4 * progress);
    }

    // Mild penalty for spreading across many bins when mean residual is high
    let mean_norm = mean_residual / cap;
    score += open_bins_count as f64 * mean_norm * mean_norm * 2.0;

    // Smooth preference for fuller bins relative to current average
    score -= (mean_residual - post) * 0.3;

    score
}

