pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Capacity fraction classes: treat residual as fifths of capacity.
    let fifth = bin_capacity / 5;
    let residual_class = bin_residual / fifth; // 0..=5
    let post_class = post_residual / fifth;

    // Reward tight fits: low post_residual class gets strong discount.
    score -= (5 - post_class as f64) * 12.0;

    // Harmonic dead-space penalty: post_residual that no plausible item (1..=100)
    // can ever fill is wasted. Penalize small unusable slivers harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Modulo logic: post_residual divisible by common item sizes is "reusable".
    let reusable = (post_residual % 10 == 0)
        || (post_residual % 20 == 0)
        || (post_residual % 25 == 0)
        || (post_residual % 50 == 0);
    if reusable {
        score -= 8.0;
    } else if post_residual > 0 {
        score += (post_residual % 10) as f64 * 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual <= 15 {
            score -= 15.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit, or lookahead suggests a better pairing elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base handicap so existing bins are preferred.
        score += 30.0 + 20.0 * progress;
        // If the next item could pair with the current one in this fresh bin,
        // opening it is attractive: discount when item + next <= capacity.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 35.0;
        }
        // Many open bins with high mean residual: opening fresh is fine.
        if open_bins_count > 6 && mean_residual > (bin_capacity as f64) * 0.4 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item cannot use this residual: slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64).min(40.0) * 0.3;
        }
    }

    // Harmonic class of item: big items (integer division thresholds) should
    // prefer bins leaving divisible residuals.
    let item_class = item_size / 20; // 0..=4
    match item_class {
        0 => { score += post_residual as f64 * 0.05; }   // tiny items: mild
        1 => { score -= 3.0; }                            // small-medium
        2 => { score -= 5.0; }                            // medium
        3 => { score -= 7.0; }                            // large
        _ => { score -= 10.0; }                           // huge items: fill aggressively
    }

    // Prefer bins below mean residual (tighter bins) slightly.
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // Penalize post_residuals that fall into the "unusable" band (too small
    // for typical future items) far more than large comfortable residuals.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 60.0; // dead space: nothing can ever use it
    } else if pr < 20.0 {
        score += 25.0; // nearly dead space
    } else if pr < 35.0 {
        score += 8.0;  // awkward gap
    } else {
        score -= 10.0; // roomy residual, still usable
    }

    // Perfect or near-perfect fits get a strong bonus.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; with few bins, be pickier.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 35.0;
        } else if slack <= 20 {
            score -= 12.0;
        }
    }
    // If next item would NOT fit here but would fit a fresh bin, mild penalty
    // for creating a residual the lookahead can't use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New empty bin candidate: default preference is to fill existing bins.
    // Only make the new bin attractive when every existing fit is bad
    // (handled above by penalties); baseline for new bin is high but not
    // infinite so bad fits lose.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening a new bin is cheaper when few bins are open (low pressure).
        score -= pressure * 4.0;
        // If the item is large relative to capacity, a fresh bin wastes less.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= frac * 25.0;
        // Late in the stream, new bins are less costly long-term.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0;
    }

    // Mean residual coupling: when the fleet average residual is low, waste
    // here hurts more; when it's high, tolerate imperfect fits.
    score += (mean_residual - pr) * 0.15;

    score
}

