pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Adaptive dead-space threshold tied to lookahead item size.
    let dead_threshold = 10.0_f64.max((next_item_size as f64 * 0.6).min(50.0));
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 24.0 + (dead_threshold - post_residual as f64) * 2.8;
    }

    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 58.0;
    } else if post_residual <= 4 {
        // Tiny gap is nearly perfect: reward closing it out.
        score -= 26.0;
    }

    // Reward tight fits relative to bin capacity, with a superlinear bonus
    // for very full placements (combats dead-space accumulation).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;
    if fill_ratio > 0.8 {
        score -= (fill_ratio - 0.8) * 60.0;
    }

    // Last fitting bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Lookahead: graded reward for leaving a residual the next item can use.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 34.0; // exact match for next item: excellent handoff
        } else if gap <= 4 {
            score -= 18.0;
        } else if gap <= 12 {
            score -= 8.0;
        } else if gap <= 24 {
            score -= 3.0;
        }
        if gap <= 2 {
            score -= 7.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual too small for next item: penalize dead-space creation.
        let waste_ratio = (post_residual as f64) / (next_item_size as f64).max(1.0);
        let soft = if post_residual <= 3 { 0.4 } else { 1.0 };
        score += (8.0 + waste_ratio * 12.0) * soft;
        // Near-miss penalties: residual just short of hosting the next item.
        let miss = next_item_size - post_residual;
        if miss <= 3 {
            score += 13.0;
        } else if miss <= 8 {
            score += 6.0;
        }
    }

    // Consolidation pressure: prefer bins whose residual sits below the mean.
    if fitting_bins_count > 2 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.35 {
        score -= 5.0;
    }
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Two-item lookahead coupling: reward residuals that can host the next
    // item with usable leftover space (soft two-step chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size {
            score -= 8.0; // residual can host next item twice: strong chain
        } else if after_next > 0 && after_next <= 6 {
            score -= 5.0; // leaves a nearly-closed gap after next placement
        } else if after_next <= 10 {
            score -= 2.0;
        }
        // Residual can also absorb the mean residual of the stream.
        if post_residual as f64 >= next_item_size as f64 + mean_residual.max(1.0) {
            score -= 4.0;
        }
    }

    // Late-stream pressure: as the stream progresses, favor compacting into
    // existing bins more aggressively to squeeze out extra bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.5 && bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    // New-bin candidate logic: open a new bin only for large items or when
    // existing fits would strand unusable space.
    if bin_residual == bin_capacity {
        let load = item_size as f64 / bin_capacity as f64;
        if load < 0.25 && fitting_bins_count > 0 {
            score -= 6.0; // small item: cheap to place anywhere, avoid new bin
        } else {
            score += 5.0 * load;
        }
        if post_residual == 0 || post_residual >= 28 {
            score -= 38.0;
        }
        // Fresh bin with room for next item is good only if nothing fits well.
        if post_residual > 0 && post_residual >= 28 && post_residual >= next_item_size && fitting_bins_count > 0 {
            score -= 6.0;
        }
        // Prefer a fresh bin when the next item is large and would be stranded
        // by any residual left behind in existing bins.
        if next_item_size >= 45 && post_residual < next_item_size && post_residual > 0 {
            score -= 20.0;
        }
        // Avoid opening a new bin for a large item when an existing bin leaves
        // a residual the next item could still consume.
        if load >= 0.25 && next_item_size > 0 && post_residual >= next_item_size {
            score += 13.0;
        }
        if fitting_bins_count == 1 {
            score += 90.0; // never open a new bin when this is the last chance
        }
        // Extra guard: with several fitting bins and a small item, strongly
        // discourage wasting a fresh bin.
        if load < 0.35 && fitting_bins_count >= 2 {
            score += 17.0;
        }
        if load < 0.6 && fitting_bins_count >= 4 {
            score += 9.0;
        }
        // Late stream: strongly discourage new bins once mostly done.
        if fitting_bins_count > 0 && progress > 0.7 {
            score += 6.0 * progress;
        }
        // A fresh bin whose post residual is exactly the next item size is a
        // perfect handoff — but only if existing bins cannot do the same.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 0 {
            score += 24.0;
        }
        // Small stranded dead space in a fresh bin with alternatives: avoid.
        if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
            score += 8.0;
        }
    } else {
        // Existing-bin branch: small dead-space handling.
        if post_residual > 0 && post_residual <= 8 && next_item_size > post_residual {
            score -= 11.0;
        }
        let res_ratio = post_residual as f64 / bin_capacity as f64;
        if res_ratio < 0.1 {
            score -= 5.0;
        }
        if post_residual > 0 && next_item_size > post_residual && (post_residual as f64) > dead_threshold * 0.5 {
            score += 5.0;
        }
        if post_residual >= 2 * next_item_size && next_item_size > 0 {
            score -= 5.0;
        }
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.4 && post_residual < next_item_size {
            score += (dead_ratio - 0.4) * 22.0 * (1.0 - progress);
        }
        if post_residual > 0 {
            let dev = ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();
            if dev < 0.05 {
                score -= 4.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual as f64 <= mean_residual * 1.2 {
                score -= 3.0;
            }
            if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
                score -= 3.5;
            }
        }
        if fitting_bins_count >= 2 && res_ratio < 0.15 && post_residual > 0 {
            score -= 2.0;
        }
        if progress > 0.6 {
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
                score -= 4.0 * (progress - 0.6) * 10.0;
            }
            if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size * 3 {
                score += 2.0 * (progress - 0.6) * 5.0;
            }
        }
        if fitting_bins_count >= 3 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 && post_residual < next_item_size && (post_residual as f64) < mean_residual * 0.4 {
            score += 4.0;
        }
        if dead_ratio > 0.6 && post_residual > 0 && post_residual < 10 && fitting_bins_count >= 1 {
            score += 6.0 * (dead_ratio - 0.6) * 10.0;
        }
        if progress > 0.8 && post_residual > 0 && post_residual <= next_item_size {
            score -= 5.0 * (progress - 0.8) * 10.0;
        }
    }

    score
}

