    score -= fill_ratio * 34.0;
    if fill_ratio > 0.75 {
        score -= (fill_ratio - 0.75) * 75.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);

    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 36.0;
        } else if gap <= 4 {
            score -= 20.0;
        } else if gap <= 12 {
            score -= 9.0;
        } else if gap <= 24 {
            score -= 3.0;
        }
        if gap <= 2 {
            score -= 8.0;
        }
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size {
            score -= 9.0;
        } else if after_next > 0 && after_next <= 6 {
            score -= 5.0;
        } else if after_next <= 10 {
            score -= 2.0;
        }
        if after_next == 2 * next_item_size {
            score -= 6.0;
        }
        if after_next >= 3 * next_item_size {
            score -= 3.0;
        }
        if post_residual as f64 >= next_item_size as f64 + mean_residual.max(1.0) {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        let waste_ratio = (post_residual as f64) / (next_item_size as f64).max(1.0);
        let soft = if post_residual <= 3 { 0.35 } else { 1.0 };
        score += (8.0 + waste_ratio * 12.0) * soft;
        let miss = next_item_size - post_residual;
        if miss <= 3 {
            score += 14.0;
        } else if miss <= 8 {
            score += 7.0;
        } else if miss <= 16 && post_residual >= 10 {
            score += 4.0;
        } else if miss <= 24 && post_residual >= 14 {
            score += 2.5;
        }
        let stranded = (post_residual as f64) / bin_capacity as f64;
        if stranded < 0.08 && miss > 8 {
            score += 10.0 * (0.08 - stranded);
        }
