            score += 4.0;
        }
        if post_residual > 0 && post_residual < next_item_size && post_residual >= 12
            && next_item_size >= 30 && fitting_bins_count >= 2 {
            score += 9.0;
        }
        if post_residual > 0 && post_residual < next_item_size && post_residual >= 20
            && fitting_bins_count >= 3 {
            score += 12.0;
        }
        if post_residual > 0 && post_residual < 28 && next_item_size > 0
