            score += 8.0;
        }
        if fitting_bins_count >= 3 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.8 {
            score += 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let chunks = post_residual as f64 / mean_residual;
            if (chunks - chunks.round()).abs() < 0.15 && chunks.round() >= 1.0 {
                score -= 4.0 * chunks.min(3.0);
            }
        }
        if progress > 0.75 && post_residual > 0 && (post_residual as f64) > mean_residual * 1.5 + 4.0 {
            score += 9.0 * (progress - 0.75) * 4.0;
        }
        if post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 <= dead_threshold * 0.4 && fitting_bins_count >= 2 {
            score += 5.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 2 * next_item_size + 3 {
            score -= 10.0;
        }
