        if next_item_size > 0 && post_residual >= 2 * next_item_size
            && post_residual - 2 * next_item_size <= 3 {
            score -= 7.0;
        }
        // New: late-stream consolidation bonus for near-full bins.
        if progress > 0.7 && res_ratio < 0.2 && post_residual > 0 {
            score -= 3.0 * progress;
        }
    }

    score
