    }

    if fitting_bins_count > 2 && post_residual > 0 && (post_residual as f64) < mean_residual * 0.35 {
        score -= 5.0;
    }
    score += (mean_residual - bin_residual as f64) * 0.3;

    if progress > 0.5 && bin_residual < bin_capacity {
        score -= progress * 10.0;
    }
    if progress > 0.85 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
