            score += 6.0 * (dead_ratio - 0.6) * 10.0;
        }
        if progress > 0.8 && post_residual > 0 && post_residual <= next_item_size {
            score -= 5.0 * (progress - 0.8) * 10.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 <= mean_residual.max(1.0) * 0.5 {
            score -= 7.0 * (1.0 - progress);
        }
    }

    score
}

