    if (post_residual as f64) < mean_residual * 0.5 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin starts from a high baseline so we only
    // open a new bin when the fit is very clean or the stream is early.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 1.5;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream, prefer consolidating into existing bins.
        score += progress * 15.0;
        // If the item is small relative to capacity, a fresh bin wastes space.
        score += (bin_capacity as f64 - item_size as f64) * 0.1;
        // Allow a new bin if no open bin fits well and item is large.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild penalty for spreading across many bins when item is small.
    if item_size < 30 && open_bins_count > 3 {
        score += 1.0;
    }

    score
}

