pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth cubic coupling of post-residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more.
    let coupling = 0.5 + 0.5 * progress;
    score += 60.0 * coupling * norm_pr.powi(3) * cap;

    // Reward tight fits via smooth saturating term
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (item_size as f64 / cap);

    // Last-chance bin: strong smooth reward scaled by progress
    if fitting_bins_count == 1 {
        score -= 25.0 + 45.0 * progress;
    }

    // Penalize bins far from mean residual (fragmentation), smoothly
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Lookahead: smooth reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let ratio = (next_item_size as f64 / cap).min(1.0);
        score -= 20.0 * fits_next * ratio * (0.5 + 0.5 * (1.0 - progress));
    }

    // Mild penalty for too many open bins, smoothed by progress
    score += (open_bins_count as f64).sqrt() * 2.0 * (0.5 + 0.5 * progress);

    // New-bin candidate: neutral-ish baseline with smooth discouragement early
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
