pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual divisible by common item sizes
    // (10, 20, 25, 50) is more likely reusable later.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 { score -= 30.0; }
        else if pr % 25 == 0 { score -= 20.0; }
        else if pr % 20 == 0 { score -= 15.0; }
        else if pr % 10 == 0 { score -= 10.0; }
        else {
            // Awkward residual: penalize dead space in the "unusable zone".
            if pr < 10 { score += 40.0; }
            else { score += 5.0; }
        }
    }

    // Integer-division thresholds on post_residual: classify into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr <= quarter && pr > 0 {
        score += 12.0; // small leftover, likely dead space unless perfectly classed
    } else if pr <= half {
        score -= 5.0; // half-class residual is flexible
    }

    // Lookahead coupling: reward residual that exactly fits the next item's class.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 60.0;
        } else if pr >= next_item_size && pr % next_item_size.max(1) == 0 {
            score -= 15.0;
        } else if next_item_size > pr && pr > 0 {
            score += 25.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate: prefer existing bins generally; make new bin costly
    // unless the item leaves a well-classed residual or nothing fits well.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 { score -= 100.0; }
        // A fresh bin gives a full harmonic residual; slightly reward when
        // the stream is young and future items are large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if next_item_size >= 50 { score -= 20.0 * progress; }
    }

    // Mild pressure toward consolidating bins when many are open.
    score += 0.3 * open_bins_count as f64;

    // Slight preference for bins whose residual is near the mean (avoid outliers).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize gaps that are too small to be
    // useful for typical future items (unusable dead space).
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Moderate penalty for gaps that can only fit very small items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: mildly discourage opening new bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 15.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        // But allow new bin if current item would leave a tight fit elsewhere
        // and next item is large (lookahead planning).
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
            score -= 20.0;
        }
    } else {
        // Slight preference for bins whose residual deviates from mean
        // (consolidate space): favor bins with residual close to item_size need.
        let diff = (bin_residual as f64 - item_size as f64).abs();
        score += diff * 0.05;
        // Favor bins below mean residual (tighter bins) to preserve big gaps.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to next item.
        score += 4.0;
    }

    score
}

