    score += (mean_residual - bin_residual as f64) * 0.3;

    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.5 && bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let load = item_size as f64 / bin_capacity as f64;
        if load < 0.25 && fitting_bins_count > 0 {
            score -= 6.0;
        } else {
            score += 5.0 * load;
        }
        if post_residual == 0 || post_residual >= 28 {
            score -= 36.0;
        }
        if post_residual > 0 && post_residual >= 28 && post_residual >= next_item_size {
            score -= 6.0;
        }
        if next_item_size >= 45 && post_residual < next_item_size && post_residual > 0 {
            score -= 20.0;
        }
        if load >= 0.25 && next_item_size > 0 && post_residual >= next_item_size {
            score += 13.0;
        }
        if fitting_bins_count == 1 {
            score += 90.0;
        }
        if load < 0.35 && fitting_bins_count >= 2 {
            score += 17.0;
        }
        if load < 0.6 && fitting_bins_count >= 4 {
            score += 9.0;
        }
        if fitting_bins_count > 0 && progress > 0.7 {
            score += 6.0 * progress;
        }
        if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
            score += 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 0 {
            score += 24.0;
        }
        if next_item_size > 0 && post_residual == 0 && load >= 0.25 && fitting_bins_count > 0 {
            score += 8.0;
        }
        if post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 5 && fitting_bins_count >= 3 {
            score += 10.0;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 2 * next_item_size + 3 {
            score -= 10.0;
        }
    } else {
        if post_residual > 0 && post_residual <= 8 && next_item_size > post_residual {
            score -= 11.0;
        }
        let res_ratio = post_residual as f64 / bin_capacity as f64;
        if res_ratio < 0.1 {
            score -= 5.0;
        }
        if post_residual == 0 && next_item_size > 0 && fitting_bins_count >= 2 {
            score -= 6.0;
        }
        if post_residual > 0 && next_item_size > post_residual && (post_residual as f64) > dead_threshold * 0.5 {
            score += 5.0;
        }
        if post_residual >= 2 * next_item_size && next_item_size > 0 {
            score -= 5.0;
        }
        if post_residual > 0 && next_item_size > post_residual && post_residual < 6 {
            score += 6.0;
        }
        let dead_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        if dead_ratio > 0.55 && fitting_bins_count > 0 && post_residual < next_item_size {
            score += 10.0 * (dead_ratio - 0.55);
        }
        if dead_ratio > 0.4 && post_residual < next_item_size {
            score += (dead_ratio - 0.4) * 22.0 * (1.0 - progress);
        }
        if post_residual > 0 {
            let dev = ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();
            if dev < 0.05 {
                score -= 4.0;
            }
            if next_item_size > 1 && post_residual % next_item_size == 0 && post_residual / next_item_size >= 2 {
                score -= 3.5;
            }
        }
        if fitting_bins_count >= 2 && res_ratio < 0.15 && post_residual > 0 {
            score -= 2.0;
        }
        if progress > 0.6 {
            if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 6 {
                score -= 4.0 * (progress - 0.6) * 10.0;
            }
            if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size * 3 {
                score += 2.0 * (progress - 0.6) * 5.0;
            }
        }
        if fitting_bins_count >= 3 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 && post_residual < next_item_size && (post_residual as f64) < mean_residual * 0.4 {
            score += 4.0;
        }
        if progress > 0.8 && post_residual > 0 && post_residual <= next_item_size {
            score -= 5.0 * (progress - 0.8) * 10.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 2 {
            score += 5.0;
        }
        if progress > 0.85 && post_residual > 0 && post_residual <= 4 {
            score -= 6.0;
        }
        if post_residual > 0 && dead_ratio > 0.45 && (post_residual as f64) < mean_residual * 0.6 && fitting_bins_count >= 1 {
            score += 3.0 * dead_ratio;
        }
        // Late-stream compaction: penalize residuals well above the mean.
        if progress > 0.75 && post_residual > 0 && (post_residual as f64) > mean_residual * 1.5 + 4.0 {
            score += 9.0 * (progress - 0.75) * 4.0;
        }
        if progress > 0.8 && post_residual > 0 && (post_residual as f64) <= mean_residual.max(1.0) {
            score -= 8.0 * (progress - 0.8) * 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // next item still fits after this placement
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // next item won't fit here; penalize small dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize leaving unusable slivers (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Compare against mean residual: prefer filling below-average-residual bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a new bin unless lookahead suggests it's useful
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 100.0;
        }
    }

    // Late in stream: prefer tighter packing, fewer open bins
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 20.0 * (1.0 - progress);
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; reward small post_residual non-linearly.
    let fit_ratio = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post_residual can host the next item (chain packing).
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that cannot serve the next item.
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score -= 3.0 * crowding * (0.5 + progress);

    // Global residual alignment: if this bin's residual is below mean, it's a
    // "small hole" — use it up; large residual bins should stay flexible.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 0.05 * ((bin_residual as f64) - mean_residual);
    }

    // New-bin candidate: only attractive when item is large relative to residual
    // landscape or nothing fits well; penalize opening bins early in the stream.
    if bin_residual == bin_capacity {
        let early_penalty = 30.0 * (1.0 - progress);
        let waste = (bin_capacity - item_size) as f64;
        score += early_penalty + 0.4 * waste;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits anywhere: must open
        }
    }

    // Late stream: tighten packing, discourage leaving large residuals behind.
    score += (1.0 - progress) * 0.0 + progress * 0.08 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = r * (1.0 + 0.5 * rn * rn);

    // Polynomial coupling of post-residual with stream progress:
    // early on, tolerate larger residuals (bins stay flexible);
    // later, aggressively penalize wasted space.
    let progress_coupling = 3.0 * progress * (1.0 - progress) * rn
        + 2.0 * progress * progress * rn * rn * cap * 0.05;
    score += progress_coupling * cap;

    // Reward tight fits (small post-residual relative to capacity)
    score -= 8.0 * (1.0 - rn) * (1.0 - rn) * (1.0 - progress);

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    // Lookahead: favor bins whose post-residual can still host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 2.0 * progress;
    }

    // Slight preference for consolidating into fewer bins
    score += 0.05 * open_bins_count as f64 * rn;

    // Penalize bins far below the mean residual (fragmented space)
    score += 0.5 * (mean_residual - r).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in a "useful"
    // residue class for small items (multiples of 10 / 5) are more valuable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest item (1..10 band)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Harmonic class reward: post_residual divisible by common item granularities
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Quantized fraction of capacity used: reward high fill ratio buckets
    let fill = 1.0 - post / cap;
    let bucket = (fill * 10.0).floor(); // integer division threshold on capacity fraction
    score -= bucket * 2.5;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residue; check harmonic class of the chain
            let chain = post_residual - next_item_size;
            if chain % 10 == 0 {
                score -= 10.0;
            }
            score -= 3.0;
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to dead space
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin wastes
    // this bin's entire residual; reward using it heavily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it less
    // attractive unless existing bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (amortized over stream progress)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + 20.0 * (1.0 - progress);

        // If the current item is large relative to capacity, a fresh bin is fine
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // If many bins are open but mean residual is small, opening new is reasonable
        if mean_residual < (item_size as f64) {
            score -= 10.0;
        }
    }

    // Mild penalty when bin's residual deviates far from mean residual (imbalance)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    // Small structural tiebreak using modulo of item size on capacity quarters
    if item_size % (bin_capacity / 4) == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    // Gaps below the minimum item size (1) can never be filled; gaps in a "dead zone"
    // (small residual that most items cannot use) are heavily penalized.
    let dead_threshold = 12.0; // residuals <= ~12 are rarely usable by typical items
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Non-linear penalty on very tight fits that leave near-zero slack is fine,
    // but perfect fits should be strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bins pressure: prefer spreading across fewer bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.35 + 0.5 * progress);
    score += pressure * 0.15;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for leaving a tempting-but-useless gap.
        score += 3.0;
    }

    // Mean-residual coupling: bins with residual far below mean are less attractive
    // unless the fit is tight (post_residual small), keeping large gaps consolidated.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.25;
    }

    // New-bin candidate: penalize slightly so it only wins when open bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Near match: next item fits with small leftover -> moderate reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 20.0 - leftover.min(20.0);
        // Bonus if the leftover is small relative to capacity.
        if leftover <= 10.0 {
            score -= 8.0;
        }
    }

    // Dead space: next item does NOT fit in the remainder -> penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.6;
        // Extra penalty if the dead space is tiny and unusable (worst case).
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // Tight fit of current item: reward small post_residual relative to bin_residual.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 10.0;

    // Compare against mean residual: filling a fatter-than-average bin is good.
    score += (mean_residual - post_residual as f64) * 0.25;

    // Last chance bin: only one bin can fit this item -> reward using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Early stream: be slightly more willing to open/use bins flexibly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Mild penalty for spreading across many open bins when a fresh bin is an option.
    if bin_residual == bin_capacity {
        // New bin baseline: prefer it only if it would beat typical placements.
        score += 6.0 + (open_bins_count as f64) * 0.4;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual = good packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful (below min item size 1..100 -> treat <15 as risky).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 15.0 {
        score += 25.0 * (15.0 - dead);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be picky, penalize mediocre fits.
        score += 4.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Lookahead: if next item fits exactly in the post-residual, reward; if next item would waste this bin's space, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx - dead as f64).abs() < 5.0 && dead >= nx {
            score -= 22.0; // sequenced chain fit
        } else if dead > 0.0 && nx > dead && nx - dead < 20.0 {
            score += 12.0; // next item nearly fits: keep more space elsewhere
        }
        // Global residual matching: prefer bins whose leftover complements the stream's typical demand.
        let avg_demand = (bin_capacity as f64 - mean_residual).max(1.0);
        let complement = (dead - nx).abs();
        score += 0.15 * complement;
        let _ = avg_demand;
    }

    // Time horizon: early in stream, encourage spreading load (open bins early to build flexibility);
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 10.0 + 40.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin early can be strategic if current bins are crowded.
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins that deviate favorably from mean residual (use the fullest bins first).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for leaving very large residuals unused when many bins are open.
    if dead > 60.0 && open_bins_count > 4 {
        score += 0.1 * (dead - 60.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (1.0 + 2.0 * progress) - pr_norm * progress;
    score += 30.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: favor bins whose post-residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 - pr).max(0.0) / bin_capacity as f64;
    }

    // Mild new-bin aversion early, tolerance late
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress);
    }

