pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit residue classes are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fit
    } else if pr <= 5 {
        score -= 200.0;
    } else if pr % 10 == 0 {
        score -= 80.0; // decade-aligned residual keeps future fits harmonic
    } else if pr < 10 {
        score += 100.0; // dead space below min item size
    }

    // Integer-division thresholds: post_residual bucket via pr/10.
    let bucket = (pr / 10) as f64;
    score += bucket * 6.0;

    // Next-item lookahead: reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 + 20.0 * (1.0 - slack / cap);
            if (pr - next_item_size) % 10 == 0 {
                score -= 25.0; // chained harmonic fit
            }
        } else {
            score += 40.0; // next item won't fit here
        }
        // Penalize residuals in awkward classes relative to next item
        if next_item_size > pr && pr % next_item_size.max(1) != 0 {
            score += 5.0;
        }
    } else {
        // Last item: waste is pure loss
        score -= 150.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        score += 8.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin only if existing fits are terrible (large post_residual dead space)
        // and stream is early enough that many items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let badness = (post_residual as f64 / cap) * (1.0 - progress);
        score += 60.0 - 50.0 * badness;
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Mean-residual coupling: if open bins are generally roomy, prefer compact fills.
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Slight pressure to keep bin count low as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * progress * (1.0 - (post_residual as f64 / cap));

    score
}

