pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but avoid tiny dead space < ~10
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver penalty
    }

    // 2-step lookahead: reward post_residual matching next item size exactly
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 / (1.0 + diff);
        // Perfect chain: post_residual exactly fits next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving space that neither fits next item nor is reusable
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: maximize packing density
        score -= 10.0;
    }

    // Prefer bins with residuals below mean (consolidate fullness)
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.5 * (mean_residual - resid_f) / cap;
    } else {
        score += 0.3 * (resid_f - mean_residual) / cap;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when no good existing fit exists
    if bin_residual == bin_capacity {
        score = cap + 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // opening a fresh bin allows a perfect pair
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Early stream: be slightly conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    score
}

