    // residual below ~10 is nearly useless, residual above ~50 is fine.
    if post_residual < 10 {
        score += 22.0 * (10.0 - post_residual as f64);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here anyway; slight penalty for wasting big residual.
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or the item would leave very poor residual elsewhere.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(0.5);
        let avg_pressure = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += 30.0 * crowd * (1.0 - avg_pressure);
        // Opening a new bin is fine for big items that would fragment a bin.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively (avoid new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 12.0 * progress;
    }

    // Favor bins already below mean residual (balancing fragmentation).
    score += ((bin_residual as f64 - mean_residual) * 0.08).max(-6.0).min(6.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit), normalized.
    let mut score = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, waste matters slightly less; late, waste is costly.
    let progress_coupling = (pr / cap).powi(2) * (0.5 + 1.5 * progress);
    score += progress_coupling;

    // Reward lookahead synergy: if the next item fits exactly into the resulting
    // residual, strongly favor this bin (smooth falloff with mismatch).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= (1.0 - slack / cap) * 0.6;
        } else {
            // Penalize residuals that cannot host the next item, scaled by how
            // far off they are (smooth quadratic).
            let miss = (nxt - pr) / cap;
            score += miss * miss * 0.4;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 0.5;
    }

    // Mild penalty for fragmenting a bin far below the mean residual
    // (keeps residual distribution balanced, smooth interaction).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 0.15 * (1.0 - progress);

    // Slight preference against opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 0.1 + 0.05 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Tightness reward: quadratic bonus for small post-residual ---
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tight) * (1.0 - tight);

    // --- Dead-space penalty: residual that nothing (>=10... but sizes 1..100 unknown) can use ---
    // Harmonic classes: post_residual mod 10 classifies "usable slot" structure.
    let pr = post_residual as i64;
    let class = pr % 10;
    if pr > 0 && pr < 10 {
        score += 25.0; // tiny unusable sliver -> strong penalty
    } else if class == 0 {
        score -= 6.0; // exact decade residual is highly reusable
    } else if class <= 2 {
        score += 3.0; // near-decade but off: awkward
    }

    // --- Lookahead coupling: reward if next item fits exactly in post_residual ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64));
        } else {
            // next item cannot use this bin's remainder; penalize proportionally
            score += 4.0 * (((next_item_size - post_residual) as f64) / (bin_capacity as f64));
        }
    }

    // --- Last-chance bin: strongly prefer using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when open bins are fragmented
        // (high mean residual spread) or many bins already struggle to fit.
        let fragmentation = (mean_residual - (post_residual as f64)).abs();
        score = bin_capacity as f64 - 0.5 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin mandatory-ish
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // Later in the stream, prefer consolidating: penalize new bins more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // --- Mild pressure against hoarding many open bins ---
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item size are toxic.
    // Anything below 10 (or below next_item_size when known) is likely wasted forever.
    let min_future_need = if next_item_size > 0 && next_item_size < 10 { next_item_size } else { 10 };
    if post_residual < min_future_need {
        score += 40.0 + 3.0 * (min_future_need - post_residual) as f64;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into fresh space;
    // prefer filling existing bins so bins can be closed out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Compare against the new-bin candidate: an empty bin has residual == capacity (score = 100
    // plus penalties). Make sure tight fits into existing bins always beat it, but a bad fit
    // (large dead space) loses to opening a fresh bin.
    let new_bin_score = bin_capacity as f64;
    if score > new_bin_score && post_residual >= min_future_need {
        // Slightly damp so we don't over-open bins, but keep bad fits penalized.
        score = new_bin_score + (score - new_bin_score) * 0.6;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }

    // Mild preference toward bins with below-average residual (consolidate emptier space).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core archetype: reward exact 2-step lookahead matches.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step fill
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot use leftover; penalize dead space proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Prefer tight fits in general
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Penalize bins far above mean residual (hoarding space), reward below-mean usage
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins would leave big dead space
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual > 0 && post_residual < 10);
        if bad_fit {
            score -= 35.0;
        } else {
            score += 20.0; // keep using existing bins when fit is decent
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly be reused by the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.55 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving space the lookahead item can consume.
            let slack = post_residual - next_item_size;
            score -= 0.25 * slack as f64;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin,
    // unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 0.10 * item_size as f64;
        if post_residual > 30 {
            score += 0.30 * (post_residual - 30) as f64;
        }
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    // or the fit into this fresh bin is genuinely good for future items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score -= 4.0 * progress;
        score += 1.5 * crowd;
        // A fresh bin is wasteful early when many bins are already open and loose.
        if mean_residual > item_size as f64 * 1.5 {
            score += 5.0;
        }
        // A fresh bin is good if the next item is large and nothing fits well.
        if next_item_size > 50 && fitting_bins_count <= 2 {
            score -= 3.0;
        }
    }

    // Mild bonus for filling bins that are already mostly consumed,
    // encouraging bin consolidation over the stream horizon.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 2.0 * fill_ratio * fill_ratio;

    // Late in the stream, prefer closing bins tightly (fewer leftovers).
    if progress_proxy(step_index, total_items) > 0.7 {
        score += 0.08 * post_residual as f64;
    }

    score
}

#[inline]
fn progress_proxy(step_index: usize, total_items: usize) -> f64 {
    step_index as f64 / (total_items.max(1) as f64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic sharpening over time
    let mut score = norm_pr * (1.0 + 1.5 * progress * norm_pr);

    // Reward tight fits: gap between residual and item
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= 0.35 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that next item could not use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 0.5 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 0.25 * (pr - nxt) / cap;
        }
