    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2 * (1.0 + progress);
    }

    // Mild pressure to consolidate: many open bins favor using existing ones
    let open_pressure = (open_bins_count as f64).ln1p();
    score += 0.1 * open_pressure * norm_pr;

    // Deviation from mean residual: prefer bins near the mean to balance residuals
    score += 0.15 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: penalize slightly so it's chosen only for poor fits,
    // with penalty easing late in the stream
    if bin_residual == bin_capacity {
        score += 0.8 + 0.6 * (1.0 - progress);
    }

    score
}

