pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small residues is worse.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = pr / cap; // fraction of capacity wasted

    // Penalize residue classes that are hard to fill (small nonzero leftovers)
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward exact fits and near-exact fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Harmonic classes via integer division thresholds on post_residual
    let class = post_residual / 20; // 0..=5
    score += match class {
        0 => -10.0,
        1 => 5.0,
        2 => 0.0,
        3 => -5.0,
        4 => 3.0,
        _ => 10.0,
    };

    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual < 10 {
        score += 12.0; // dead space that won't serve the next item
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open new bin when current fit is terrible
    if bin_residual == bin_capacity {
        // neutral base; adjust by stream position and congestion
        score = cap - post_residual as f64 + frac * 10.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        if item_size >= 50 {
            score -= 5.0; // large items: fresh bin is fine
        }
        if mean_residual < item_size as f64 * 1.2 {
            score -= 8.0; // open bins are congested
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64;

    // Modulo coupling: residues congruent to common item sizes are reusable
    let mod_class = post_residual % 10;
    if mod_class == 0 {
        score -= 6.0;
    } else if mod_class <= 3 {
        score += 3.0;
    }

    score
}

